fields.InputDefinition:
{
  "goal": "Open the 'Course Enrollments' entity grid — type 'Course Enrollments' in the LEFT sidebar 'Search record types...' box and click it (or navigate to http://localhost:4200/app/data-explorer/Data?entity=MoreCheese:%20Course%20Enrollments). Click a row (for example an enrollment of Elena Rodriguez), then 'Open Full Record'. The form has foreign-key fields (e.g. Person, Course). Next to a foreign-key field's value is a small OPEN/NAVIGATE icon (an up-right arrow / external-link icon). Click that icon on one FK field (e.g. Person) to open the RELATED record. Verify a DIFFERENT record's form opens (the URL changes to a different entity/record, e.g. a People record). Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "Started on a Course Enrollment record and used a foreign-key field's open/navigate icon",
    "A DIFFERENT related record opened (URL changed to another entity/record, e.g. a People or Courses record)",
    "No error messages or crash pages"
  ]
}
